using System;
using System.Collections.Generic;
using UnityEngine;

namespace SHHH.Game
{
    /// <summary>
    /// Astra character art (V2 reduced meshes; V3 polished locomotion clips + V2 action clips), generated by the Editor
    /// command `build_character_catalog` into Resources/CharacterCatalog. Missing entries fall back to procedural characters.
    /// Clip names used at runtime: idle, walk, run, react, carry, celebrate, shush, surprised, grab, setdown, panic,
    /// sleep, wake, situp, stand, scan, point, admonish, squint, inspect, returnbed, opendoor, eat, jump, startle, sniff, wag, sit, pick.
    /// </summary>
    [CreateAssetMenu(menuName = "SHHH/Character Catalog")]
    public sealed class CharacterCatalog : ScriptableObject
    {
        [Serializable] public sealed class NamedClip { public string name; public AnimationClip clip; }

        [Serializable]
        public sealed class Entry
        {
            public string key;                 // pip, nell, rory, tess, mom, mochi, biscuit
            public GameObject model;
            public float height = 1.3f;        // metres (top of head)
            public int triangles;
            public List<NamedClip> clips = new List<NamedClip>();
            public AnimationClip Clip(string n) { foreach (var c in clips) if (c != null && c.name == n && c.clip != null) return c.clip; return null; }
        }

        public List<Entry> characters = new List<Entry>();
        static CharacterCatalog _i; static bool _tried;
        public static CharacterCatalog I { get { if (_i == null && !_tried) { _tried = true; _i = Resources.Load<CharacterCatalog>("CharacterCatalog"); } return _i; } }
        public Entry Get(string key) { if (string.IsNullOrEmpty(key)) return null; foreach (var e in characters) if (e != null && e.key == key && e.model != null) return e; return null; }
        public static readonly string[] SiblingKeys = { "pip", "nell", "rory", "tess" };
    }
}
